/// <summary>One classified auto-wrong line: the census TSV row plus the stderr-only annotations.</summary>
public sealed record ClassificationResult
{
	/// <summary>Holdout identity of the line.</summary>
	public required string HoldoutId { get; init; }

	/// <summary>Zero-based line index within the recipe.</summary>
	public required int LineIndex { get; init; }

	/// <summary>The trace set the line came from.</summary>
	public required string Set { get; init; }

	/// <summary>Relation class: no-label, pack-unit-state, compound-head-lost, state-mismatch, row-choice-tier, same-head-other-qualifier, sibling-food, other.</summary>
	public required string Relation { get; init; }

	/// <summary>Site: reuse, ranker, override, or curated.</summary>
	public required string Site { get; init; }

	/// <summary>For site=override: <c>yes</c>/<c>no</c> — the normalised rawText is a key in exact-overrides.json.</summary>
	public string? OverrideKey { get; init; }

	/// <summary>The accepted row's data type tier.</summary>
	public string AcceptedTier { get; init; } = string.Empty;

	/// <summary>The key row's data type tier.</summary>
	public string KeyTier { get; init; } = string.Empty;

	/// <summary>The accepted row's combined FoodState mask (candidate state | satisfiers).</summary>
	public string AcceptedState { get; init; } = string.Empty;

	/// <summary>The key row's combined FoodState mask (candidate state | satisfiers).</summary>
	public string KeyState { get; init; } = string.Empty;

	/// <summary>The atom's parsed name, verbatim.</summary>
	public string ParsedName { get; init; } = string.Empty;

	/// <summary>The key head phrase (head term plus non-state qualifier words), singularised and space-joined.</summary>
	public string KeyHead { get; init; } = string.Empty;

	/// <summary>The accepted row's description.</summary>
	public string AcceptedDesc { get; init; } = string.Empty;

	/// <summary>The key row's description.</summary>
	public string KeyDesc { get; init; } = string.Empty;

	/// <summary>The raw recipe line.</summary>
	public string RawText { get; init; } = string.Empty;

	/// <summary>Set when a field the brief's relation ladder needs is missing from the trace (the line is classified <c>other</c>).</summary>
	public string? MissingField { get; init; }

	/// <summary>For row-choice-tier: which tier is higher — <c>key</c>, <c>accepted</c>, or empty.</summary>
	public string? TierDirection { get; init; }

	/// <summary>For same-head-other-qualifier: the qualifier words present on the key but not the accepted row, and vice versa.</summary>
	public (string KeyOnly, string AcceptedOnly)? QualifierDiff { get; init; }
}
