{"content":"using System.Text.Json;

using LetUsCook.Fdc.Lexicon;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// The key set of <c>Lexicon/Resources/exact-overrides.json</c>, read from the embedded resource of the
/// production assembly — the file the brief names, not a copy of it. Lookup uses the same cleaning
/// <c>FdcMatcher.MatchAsync</c> applies before its raw-override probe (FdcMatcher.cs:165): cut at the
/// first parenthesis, trim, lowercase. <c>StripFromParenthesis</c> itself is private in the matcher, so
/// this one-line cut is the nearest reachable equivalent (brief §8).
/// </summary>
public sealed class ExactOverrideKeyIndex
{
	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	private readonly FrozenSet<string> _keys;

	/// <summary>Loads the key set from the embedded resource.</summary>
	public ExactOverrideKeyIndex()
	{
		var assembly = typeof(FdcNormalizer).Assembly;
		var name = assembly.GetManifestResourceNames().Single(n => n.EndsWith("exact-overrides.json", StringComparison.Ordinal));
		using var stream = assembly.GetManifestResourceStream(name)
			?? throw new InvalidOperationException($"Embedded resource '{name}' not found.");
		using var reader = new StreamReader(stream);
		var entries = JsonSerializer.Deserialize<Dictionary<string, JsonElement>>(reader.ReadToEnd(), JsonOptions)
			?? throw new InvalidOperationException("exact-overrides.json was empty.");
		_keys = entries.Keys.ToFrozenSet(StringComparer.OrdinalIgnoreCase);
	}

	/// <summary>Number of keys in the file.</summary>
	public int Count => _keys.Count;

	/// <summary>Whether the cleaned raw text is a key in the file.</summary>
	/// <param name="rawText">The raw recipe line text.</param>
	public bool IsKey(string rawText)
	{
		ArgumentNullException.ThrowIfNull(rawText);
		return _keys.Contains(NormalizeForOverrideLookup(rawText));
	}

	/// <summary>Cut at the first parenthesis, trim, lowercase — the matcher's raw-override key cleaning.</summary>
	/// <param name="rawText">The raw recipe line text.</param>
	/// <returns>The cleaned key candidate.</returns>
	public static string NormalizeForOverrideLookup(string rawText)
	{
		ArgumentNullException.ThrowIfNull(rawText);
		var text = rawText.Trim();
		var paren = text.IndexOf('(', StringComparison.Ordinal);
		if (paren >= 0)
		{
			text = text[..paren];
		}

#pragma warning disable CA1308 // Reason: parity with FdcMatcher.MatchAsync's nameClean folding (FdcMatcher.cs:165).
		return text.Trim().ToLowerInvariant();
#pragma warning restore CA1308
	}
}
