{"content":"using System.Text.RegularExpressions;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line on the two axes the P12.13 brief defines — relation
/// (accepted row vs key row) and site (where the line was accepted) — using the production
/// state/head helpers only (D-014: the matcher logic is called, never copied).
/// </summary>
public sealed partial class AutoWrongClassifier
{
	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;

	// Reused single-token list so the per-token state probe calls the production
	// ExtractCandidateState/ExtractCandidateSatisfiers without a constant-array argument (CA1861).
	private readonly List<string> _singleToken = [];

	/// <summary>Creates the classifier.</summary>
	/// <param name="normalizer">The production token normalizer.</param>
	/// <param name="overrideKeys">The <c>exact-overrides.json</c> key index.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		_normalizer = normalizer ?? throw new ArgumentNullException(nameof(normalizer));
		_overrideKeys = overrideKeys ?? throw new ArgumentNullException(nameof(overrideKeys));
	}

	/// <summary>Relation: the labelled row is empty.</summary>
	public const string NoLabel = "no-label";

	/// <summary>Relation: a can/jar unit line whose key is Canned and the accepted row is not.</summary>
	public const string PackUnitState = "pack-unit-state";

	/// <summary>Relation: the key's head phrase has two or more words and the parsed name is only its first word.</summary>
	public const string CompoundHeadLost = "compound-head-lost";

	/// <summary>Relation: head terms agree and the FoodState masks differ.</summary>
	public const string StateMismatch = "state-mismatch";

	/// <summary>Relation: head terms and state agree and the dataset tier differs.</summary>
	public const string RowChoiceTier = "row-choice-tier";

	/// <summary>Relation: head terms agree and nothing above holds.</summary>
	public const string SameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>Relation: head terms differ.</summary>
	public const string SiblingFood = "sibling-food";

	/// <summary>Relation: nothing above holds, or a field the check needs is missing.</summary>
	public const string Other = "other";

	/// <summary>Site: the line reused an existing row through the ranker path.</summary>
	public const string SiteReuse = "reuse";

	/// <summary>Site: the line took the exact-override path.</summary>
	public const string SiteOverride = "override";

	/// <summary>Site: the line took the curated catalogue path.</summary>
	public const string SiteCurated = "curated";

	/// <summary>Site: the line matched fresh through the ranker.</summary>
	public const string SiteRanker = "ranker";

	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();

	/// <summary>
	/// Classifies one auto-wrong line. The first relation rule that holds wins, in the brief's
	/// order; the site comes from the atom's <c>path</c>/<c>reused</c> fields.
	/// </summary>
	/// <param name="line">The trace line (<c>auto == true</c>, <c>correct == false</c>).</param>
	/// <returns>The classification; <see cref="ClassificationResult.Site"/> is empty when the atom path is unknown.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		ArgumentNullException.ThrowIfNull(line);

		var keyDesc = line.ExpectedDescriptions.Count > 0 ? line.ExpectedDescriptions[0] : string.Empty;
		var accDesc = line.ActualDescriptions.Count > 0 ? line.ActualDescriptions[0] : string.Empty;
		var keyType = line.ExpectedDataTypes.Count > 0 ? line.ExpectedDataTypes[0] : string.Empty;
		var accType = line.ActualDataTypes.Count > 0 ? line.ActualDataTypes[0] : string.Empty;

		var atom = line.Atoms.FirstOrDefault(a => a.Outcome == "accepted") ?? line.Atoms.FirstOrDefault();
		var parsedName = atom?.ParsedName ?? string.Empty;
		var site = ClassifySite(atom);

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var accTokens = _normalizer.NormalizeToTokens(accDesc);
		var keyState = CombinedState(keyTokens);
		var accState = CombinedState(accTokens);

		var keyHead = SingularPhrase(FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyType)).HeadTerm);
		var accHead = accDesc.Length > 0 ? SingularPhrase(FdcDescriptionParser.Parse(accDesc, DatasetOf(accType)).HeadTerm) : [];
		var parsedNameTokens = SingularPhrase(parsedName);
		var keyPhrase = KeyHeadPhrase(keyTokens);

		var relation = ClassifyRelation(line, keyDesc, accDesc, keyType, accType, keyState, accState, keyHead, accHead, parsedNameTokens, keyPhrase, out var missingField, out var keyOnly, out var accOnly);

		return new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			Relation = relation,
			Site = site,
			OverrideKey = site == SiteOverride ? (_overrideKeys.Contains(NormalizeForOverrideKey(line.RawText)) ? "yes" : "no") : string.Empty,
			AcceptedTier = accType,
			KeyTier = keyType,
			AcceptedState = accState.ToString(),
			KeyState = keyState.ToString(),
			ParsedName = parsedName,
			KeyHead = string.Join(' ', keyPhrase),
			AcceptedDesc = accDesc,
			KeyDesc = keyDesc,
			RawText = line.RawText,
			MissingField = missingField,
			KeyOnlyQualifiers = keyOnly,
			AcceptedOnlyQualifiers = accOnly,
		};
	}

	/// <summary>The state ∪ satisfiers mask a description's tokens carry, from the production matcher helpers.</summary>
	/// <param name="tokens">Normalized description tokens.</param>
	/// <returns>The combined <see cref="FoodState"/> mask.</returns>
	public static FoodState CombinedState(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	/// <summary>
	/// The key's head phrase: the leading description tokens up to (not including) the first token
	/// the production state/modifier vocabulary marks as a state word. "Bread, crumbs, dry, grated,
	/// plain" is the head phrase "bread crumbs"; "Tomatoes, crushed, canned" is "tomato".
	/// </summary>
	/// <param name="tokens">Normalized key description tokens.</param>
	/// <returns>The head phrase tokens, in order.</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> tokens)
	{
		var phrase = new List<string>(tokens.Count);
		foreach (var token in tokens)
		{
			if (IsStateWord(token))
			{
				break;
			}

			phrase.Add(token);
		}

		return phrase;
	}

	/// <summary>
	/// The production override-lookup key form for a raw line: trimmed, lower-cased, cut at the
	/// first parenthesis (the same cut <c>FdcMatcher</c> applies before its raw-key lookup — its
	/// <c>StripFromParenthesis</c> is private, so the cut is applied here; the key set itself is the
	/// production <c>exact-overrides.json</c>).
	/// </summary>
	/// <param name="rawText">The raw line text.</param>
	/// <returns>The normalized key candidate.</returns>
	public static string NormalizeForOverrideKey(string rawText)
	{
		var text = rawText.Trim().ToLowerInvariant();
		var paren = text.IndexOf('(', StringComparison.Ordinal);
		if (paren >= 0)
		{
			text = text[..paren].Trim();
		}

		return text;
	}

	private static string ClassifySite(TraceAtom? atom)
	{
		if (atom is null)
		{
			return string.Empty;
		}

		return atom.Path switch
		{
			"override" => SiteOverride,
			"curated" => SiteCurated,
			"ranker" => atom.Reused ? SiteReuse : SiteRanker,
			_ => string.Empty,
		};
	}

	private string ClassifyRelation(
		TraceLine line,
		string keyDesc,
		string accDesc,
		string keyType,
		string accType,
		FoodState keyState,
		FoodState accState,
		IReadOnlyList<string> keyHead,
		IReadOnlyList<string> accHead,
		IReadOnlyList<string> parsedNameTokens,
		IReadOnlyList<string> keyPhrase,
		out string? missingField,
		out IReadOnlyList<string>? keyOnly,
		out IReadOnlyList<string>? accOnly)
	{
		missingField = null;
		keyOnly = null;
		accOnly = null;

		// 1. no-label: the labelled row is empty.
		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			return NoLabel;
		}

		// 2. pack-unit-state: a can/jar unit in the raw line, the key is Canned, the accepted row is not.
		if (PackUnitRegex().IsMatch(line.RawText)
			&& (keyState & FoodState.Canned) != FoodState.None
			&& (accState & FoodState.Canned) == FoodState.None)
		{
			return PackUnitState;
		}

		// 3. compound-head-lost: the key's head phrase has two or more words and the parsed name
		//    is only its first word, after singularising.
		if (keyPhrase.Count >= 2
			&& parsedNameTokens.Count == 1
			&& string.Equals(parsedNameTokens[0], IngredientLineResolver.SingularizeToken(keyPhrase[0]), StringComparison.OrdinalIgnoreCase))
		{
			return CompoundHeadLost;
		}

		var headsAgree = keyHead.SequenceEqual(accHead, StringComparer.OrdinalIgnoreCase);

		// 4. state-mismatch: the head terms agree and the FoodState masks differ.
		if (headsAgree && keyState != accState)
		{
			return StateMismatch;
		}

		// 5. row-choice-tier: head terms and state agree and the dataset tier differs.
		if (headsAgree && keyState == accState)
		{
			if (keyType.Length == 0 || accType.Length == 0)
			{
				missingField = keyType.Length == 0 ? "expectedDataTypes" : "actualDataTypes";
				return Other;
			}

			if (!string.Equals(keyType, accType, StringComparison.OrdinalIgnoreCase))
			{
				return RowChoiceTier;
			}

			// 6. same-head-other-qualifier: the head terms agree and nothing above holds.
			var keyQualifiers = SingularPhraseList(FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyType)).Qualifiers);
			var accQualifiers = accDesc.Length > 0
				? SingularPhraseList(FdcDescriptionParser.Parse(accDesc, DatasetOf(accType)).Qualifiers)
				: (IReadOnlyList<string>?)[];
			keyOnly = keyQualifiers.Where(q => !accQualifiers.Contains(q, StringComparer.OrdinalIgnoreCase)).OrderBy(q => q, StringComparer.Ordinal).ToArray();
			accOnly = accQualifiers.Where(q => !keyQualifiers.Contains(q, StringComparer.OrdinalIgnoreCase)).OrderBy(q => q, StringComparer.Ordinal).ToArray();
			return SameHeadOtherQualifier;
		}

		// 7. sibling-food: the head terms differ.
		return SiblingFood;
	}

	private bool IsStateWord(string token)
	{
		if (FdcLexicon.Default.ModifierWords.Contains(token))
		{
			return true;
		}

		_singleToken.Clear();
		_singleToken.Add(token);
		return FdcMatcher.ExtractCandidateState(_singleToken) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleToken) != FoodState.None;
	}

	private IReadOnlyList<string> SingularPhrase(string text) =>
		SingularPhraseList(_normalizer.NormalizeToTokens(text));

	private IReadOnlyList<string> SingularPhraseList(IReadOnlyList<string> tokens) =>
		tokens.Select(IngredientLineResolver.SingularizeToken).ToArray();

	private static FdcDataset DatasetOf(string dataType) =>
		Enum.TryParse<FdcDataset>(dataType, ignoreCase: true, out var dataset) ? dataset : FdcDataset.None;
}
