{"content":"using System.Text.RegularExpressions;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line on the two axes the P12.13 brief defines: the
/// accepted-row vs key-row <c>relation</c> and the decision <c>site</c>. Every comparison uses the
/// production helpers (FdcNormalizer, FdcMatcher state extraction, FdcDescriptionParser,
/// IngredientLineResolver.SingularizeToken) — D-014: the census must measure what the matcher does,
/// so it reuses the matcher's own functions rather than a copy.
/// </summary>
public sealed partial class AutoWrongClassifier
{
	/// <summary>Relation: the labelled side is empty.</summary>
	public const string NoLabel = "no-label";

	/// <summary>Relation: rawText names a can/jar unit; the key is Canned, the accepted row is not.</summary>
	public const string PackUnitState = "pack-unit-state";

	/// <summary>Relation: the key's head phrase has two or more words and the parsedName is only its first word.</summary>
	public const string CompoundHeadLost = "compound-head-lost";

	/// <summary>Relation: the head terms agree and the state masks differ.</summary>
	public const string StateMismatch = "state-mismatch";

	/// <summary>Relation: head and state agree and the dataset tier differs.</summary>
	public const string RowChoiceTier = "row-choice-tier";

	/// <summary>Relation: head, state and tier agree; the qualifier words differ.</summary>
	public const string SameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>Relation: the head terms differ.</summary>
	public const string SiblingFood = "sibling-food";

	/// <summary>Relation: nothing above held (or a check's field was missing).</summary>
	public const string Other = "other";

	/// <summary>Site: the line reused an existing row through the ranker path.</summary>
	public const string SiteReuse = "reuse";

	/// <summary>Site: the exact/special-case override path decided the row.</summary>
	public const string SiteOverride = "override";

	/// <summary>Site: the curated catalogue decided the row.</summary>
	public const string SiteCurated = "curated";

	/// <summary>Site: the ranker fetched and ranked the row (no reuse).</summary>
	public const string SiteRanker = "ranker";

	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;

	// Reused single-element list so the per-token state checks call the production
	// ExtractCandidateState/ExtractCandidateSatisfiers without allocating a constant array (CA1861).
	private readonly List<string> _singleToken = [string.Empty];

	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();

	/// <summary>Creates a classifier over the production normalizer and the override key set.</summary>
	/// <param name="normalizer">The production FDC normalizer.</param>
	/// <param name="overrideKeys">The embedded <c>exact-overrides.json</c> key set.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		_normalizer = normalizer ?? throw new ArgumentNullException(nameof(normalizer));
		_overrideKeys = overrideKeys ?? throw new ArgumentNullException(nameof(overrideKeys));
	}

	/// <summary>
	/// Classifies one auto-wrong line. The first relation rule that holds wins (brief §4 order);
	/// the site comes from the accepted atom's <c>path</c>/<c>reused</c> fields.
	/// </summary>
	/// <param name="line">The trace line (<c>auto == true &amp;&amp; correct == false</c>).</param>
	/// <returns>The classification; <see cref="ClassificationResult.Site"/> is empty when the atom path is unknown.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		ArgumentNullException.ThrowIfNull(line);

		var atom = line.Atoms.FirstOrDefault(a => a.Outcome == "accepted") ?? line.Atoms.FirstOrDefault();
		var parsedName = atom?.ParsedName ?? string.Empty;
		var linkedIngredientId = atom?.LinkedIngredientId;

		var keyDesc = line.ExpectedDescriptions.FirstOrDefault() ?? string.Empty;
		var acceptedDesc = line.ActualDescriptions.FirstOrDefault() ?? string.Empty;
		var keyTier = line.ExpectedDataTypes.FirstOrDefault() ?? string.Empty;
		var acceptedTier = line.ActualDataTypes.FirstOrDefault() ?? string.Empty;

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var acceptedTokens = _normalizer.NormalizeToTokens(acceptedDesc);
		var keyState = CombinedState(keyTokens);
		var acceptedState = CombinedState(acceptedTokens);

		var keyHeadParsed = FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier));
		var acceptedHeadParsed = FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier));
		var keyHeadTokens = SingularPhrase(keyHeadParsed.HeadTerm);
		var acceptedHeadTokens = SingularPhrase(acceptedHeadParsed.HeadTerm);
		var parsedNameTokens = SingularPhrase(parsedName);
		var keyHeadPhrase = KeyHeadPhrase(keyTokens);

		var site = ClassifySite(atom?.Path, atom?.Reused ?? false, line.RawText, out var overrideKey);

		var relation = string.Empty;
		string? missingField = null;
		IReadOnlyList<string>? keyOnlyQualifiers = null;
		IReadOnlyList<string>? acceptedOnlyQualifiers = null;

		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			relation = NoLabel;
		}
		else if (PackUnitRegex().IsMatch(line.RawText)
			&& (keyState & FoodState.Canned) != FoodState.None
			&& (acceptedState & FoodState.Canned) == FoodState.None)
		{
			relation = PackUnitState;
		}
		else if (keyHeadPhrase.Count >= 2
			&& parsedNameTokens.Count == 1
			&& string.Equals(parsedNameTokens[0], IngredientLineResolver.SingularizeToken(keyHeadPhrase[0]), StringComparison.OrdinalIgnoreCase))
		{
			relation = CompoundHeadLost;
		}
		else if (keyHeadTokens.SequenceEqual(acceptedHeadTokens, StringComparer.OrdinalIgnoreCase))
		{
			if (keyState != acceptedState)
			{
				relation = StateMismatch;
			}
			else if (string.IsNullOrWhiteSpace(keyTier) || string.IsNullOrWhiteSpace(acceptedTier))
			{
				relation = Other;
				missingField = string.IsNullOrWhiteSpace(acceptedTier) ? "actualDataTypes" : "expectedDataTypes";
			}
			else if (!string.Equals(keyTier, acceptedTier, StringComparison.OrdinalIgnoreCase))
			{
				relation = RowChoiceTier;
			}
			else
			{
				relation = SameHeadOtherQualifier;
				keyOnlyQualifiers = QualifierDiff(keyHeadParsed.Qualifiers, acceptedHeadParsed.Qualifiers, keyOnly: true);
				acceptedOnlyQualifiers = QualifierDiff(keyHeadParsed.Qualifiers, acceptedHeadParsed.Qualifiers, keyOnly: false);
			}
		}
		else
		{
			relation = SiblingFood;
		}

		return new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			Relation = relation,
			Site = site,
			OverrideKey = overrideKey,
			AcceptedTier = acceptedTier,
			KeyTier = keyTier,
			AcceptedState = acceptedState.ToString(),
			KeyState = keyState.ToString(),
			ParsedName = parsedName,
			KeyHead = string.Join(' ', keyHeadPhrase),
			AcceptedDesc = acceptedDesc,
			KeyDesc = keyDesc,
			RawText = line.RawText,
			MissingField = missingField,
			KeyOnlyQualifiers = keyOnlyQualifiers,
			AcceptedOnlyQualifiers = acceptedOnlyQualifiers,
		};
	}

	/// <summary>
	/// The key head phrase: the key description's normalized tokens up to the first token the
	/// production state vocabulary flags (a <c>ModifierWords</c> member, or a token the production
	/// <c>ExtractCandidateState</c>/<c>ExtractCandidateSatisfiers</c> calls report state for).
	/// "Bread, crumbs, dry, grated, plain" → <c>bread crumbs</c>; "Tomatoes, crushed, canned" → <c>tomato</c>.
	/// </summary>
	/// <param name="keyTokens">The key description's normalized tokens.</param>
	/// <returns>The head-phrase tokens (singularised).</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> keyTokens)
	{
		ArgumentNullException.ThrowIfNull(keyTokens);
		var phrase = new List<string>();
		foreach (var token in keyTokens)
		{
			if (IsStateWord(token))
			{
				break;
			}

			phrase.Add(IngredientLineResolver.SingularizeToken(token));
		}

		return phrase;
	}

	/// <summary>Maps a trace dataset tier to the <see cref="FdcDataset"/> the description parser needs.</summary>
	/// <param name="tier">The tier string from the trace.</param>
	/// <returns>The dataset; <see cref="FdcDataset.None"/> when the tier is missing or unknown.</returns>
	public static FdcDataset DatasetOf(string tier)
		=> Enum.TryParse<FdcDataset>(tier, ignoreCase: true, out var dataset) ? dataset : FdcDataset.None;

	/// <summary>
	/// The state mask the production matcher computes for one row: <c>ExtractCandidateState</c> ∪
	/// <c>ExtractCandidateSatisfiers</c> over the row's normalized tokens — the same composition
	/// <c>FdcMatcher</c> feeds <c>StateAgrees</c>.
	/// </summary>
	/// <param name="tokens">The row's normalized tokens.</param>
	/// <returns>The combined mask.</returns>
	public static FoodState CombinedState(IReadOnlyList<string> tokens)
		=> FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	/// <summary>
	/// The ranker path's own reuse rule applied to the line's parsed name and the linked master slug —
	/// reported in the stderr summary for <c>reuse</c>-site lines (D-014: the production
	/// <c>ShouldReuse</c>, not a copy).
	/// </summary>
	/// <param name="parsedName">The parser name from the trace.</param>
	/// <param name="linkedIngredientId">The linked master slug.</param>
	/// <returns><see langword="true"/> when the production rule says the reuse was by exact phrase.</returns>
	public static bool ShouldReuseParsedName(string parsedName, string linkedIngredientId)
	{
		if (string.IsNullOrWhiteSpace(parsedName) || string.IsNullOrWhiteSpace(linkedIngredientId))
		{
			return false;
		}

		return IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(parsedName), linkedIngredientId);
	}

	private static string ClassifySite(string? path, bool reused, string rawText, out string overrideKey)
	{
		overrideKey = string.Empty;
		if (path is null)
		{
			return string.Empty;
		}

		return path.ToLowerInvariant() switch
		{
			"override" => SiteOverride,
			"curated" => SiteCurated,
			"ranker" => reused ? SiteReuse : SiteRanker,
			_ => string.Empty,
		};
	}

	private string QualifierDiff(IReadOnlyList<string> keyQualifiers, IReadOnlyList<string> acceptedQualifiers, bool keyOnly)
	{
		var keySet = new HashSet<string>(keyQualifiers.Select(IngredientLineResolver.SingularizeToken), StringComparer.OrdinalIgnoreCase);
		var acceptedSet = new HashSet<string>(acceptedQualifiers.Select(IngredientLineResolver.SingularizeToken), StringComparer.OrdinalIgnoreCase);
		var diff = keyOnly ? keySet.Except(acceptedSet) : acceptedSet.Except(keySet);
		return string.Join(' ', diff.OrderBy(w => w, StringComparer.OrdinalIgnoreCase));
	}

	private IReadOnlyList<string> SingularPhrase(string? text)
		=> _normalizer.NormalizeToTokens(text).Select(IngredientLineResolver.SingularizeToken).ToArray();

	private bool IsStateWord(string token)
	{
		if (FdcLexicon.Default.ModifierWords.Contains(token))
		{
			return true;
		}

		_singleToken[0] = token;
		return FdcMatcher.ExtractCandidateState(_singleToken) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleToken) != FoodState.None;
	}
}
