{"content":"using System.Text.RegularExpressions;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line on the two axes the P12.13 brief defines —
/// <em>relation</em> (accepted row vs key row) and <em>site</em> (where the line was accepted) —
/// using the production helpers only (D-014): <see cref="FdcNormalizer.NormalizeToTokens"/>,
/// <see cref="FdcMatcher.ExtractCandidateState"/>, <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>,
/// <see cref="FdcDescriptionParser.Parse(string, FdcDataset, string?)"/>'s head term, and
/// <see cref="IngredientLineResolver.SingularizeToken"/>. No matcher logic is copied here.
/// </summary>
public sealed partial class AutoWrongClassifier
{
	/// <summary>Relation: the key has no label at all.</summary>
	public const string NoLabel = "no-label";

	/// <summary>Relation: the raw line names a can/jar unit, the key's state has Canned, the accepted row's does not.</summary>
	public const string PackUnitState = "pack-unit-state";

	/// <summary>Relation: the key's head phrase has two or more words and the parsed name keeps only its first.</summary>
	public const string CompoundHeadLost = "compound-head-lost";

	/// <summary>Relation: the head terms agree after singularising and the state masks differ.</summary>
	public const string StateMismatch = "state-mismatch";

	/// <summary>Relation: head and state agree and the dataset tier differs.</summary>
	public const string RowChoiceTier = "row-choice-tier";

	/// <summary>Relation: head, state and tier agree and only the remaining qualifiers differ.</summary>
	public const string SameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>Relation: the head terms differ.</summary>
	public const string SiblingFood = "sibling-food";

	/// <summary>Relation: nothing above held, or a relation check lacked a trace field.</summary>
	public const string Other = "other";

	/// <summary>Site: the line reused an existing master row through the ranker path.</summary>
	public const string SiteReuse = "reuse";

	/// <summary>Site: the line went through the curated catalogue.</summary>
	public const string SiteCurated = "curated";

	/// <summary>Site: the line went through the exact/mint override tables.</summary>
	public const string SiteOverride = "override";

	/// <summary>Site: the line was accepted by the ranker without reuse.</summary>
	public const string SiteRanker = "ranker";

	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;

	// Single-threaded scratch slot so the per-token state check calls the production
	// Extract* helpers without allocating a list per token (CA1861). The classifier is
	// used by exactly one runner thread.
	private readonly string?[] _singleTokenScratch = new string[1];

	/// <summary>Creates a classifier over the production normalizer and the embedded override key set.</summary>
	/// <param name="normalizer">The production <see cref="FdcNormalizer"/>.</param>
	/// <param name="overrideKeys">The <c>exact-overrides.json</c> key index.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		_normalizer = normalizer ?? throw new ArgumentNullException(nameof(normalizer));
		_overrideKeys = overrideKeys ?? throw new ArgumentNullException(nameof(overrideKeys));
	}

	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();

	/// <summary>
	/// Classifies one auto-wrong line (<c>auto == true &amp;&amp; correct == false</c>).
	/// The first relation that holds wins, in the brief's order; a relation whose check needs a
	/// trace field the line does not carry classifies as <see cref="Other"/> and names the field
	/// in <see cref="ClassificationResult.MissingField"/>.
	/// </summary>
	/// <param name="line">The trace line.</param>
	/// <returns>The classification; <see cref="ClassificationResult.Site"/> is empty when the atom path is unknown.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		ArgumentNullException.ThrowIfNull(line);

		var keyDesc = line.ExpectedDescriptions.FirstOrDefault(string => !string.IsNullOrWhiteSpace(string));
		var acceptedDesc = line.ActualDescriptions.FirstOrDefault(string => !string.IsNullOrWhiteSpace(string));
		var keyTier = line.ExpectedDataTypes.FirstOrDefault(string => !string.IsNullOrWhiteSpace(string));
		var acceptedTier = line.ActualDataTypes.FirstOrDefault(string => !string.IsNullOrWhiteSpace(string));
		var atom = line.Atoms.FirstOrDefault(a => a.Outcome == "accepted") ?? line.Atoms.FirstOrDefault();

		var site = ClassifySite(atom);
		var overrideKey = site == SiteOverride ? (_overrideKeys.IsKey(NormalizeForOverrideKey(line.RawText)) ? "yes" : "no") : string.Empty;

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var acceptedTokens = _normalizer.NormalizeToTokens(acceptedDesc);
		var keyState = CombinedState(keyTokens);
		var acceptedState = CombinedState(acceptedTokens);

		var keyParsed = FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier));
		var acceptedParsed = acceptedDesc is null ? null : FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier));
		var keyHead = SingularPhrase(keyParsed.HeadTerm);
		var acceptedHead = acceptedParsed is null ? [] : SingularPhrase(acceptedParsed.HeadTerm);
		var parsedName = SingularPhrase(atom?.ParsedName);
		var keyPhrase = KeyHeadPhrase(keyTokens);

		var relation = Other;
		var missingField = (string?)null;
		IReadOnlyList<string>? keyOnly = null;
		IReadOnlyList<string>? acceptedOnly = null;

		if (keyDesc is null)
		{
			relation = NoLabel;
		}
		else if (PackUnitRegex().IsMatch(line.RawText)
			&& (keyState & FoodState.Canned) != FoodState.None
			&& (acceptedState & FoodState.Canned) == FoodState.None)
		{
			relation = PackUnitState;
		}
		else if (keyPhrase.Count >= 2 && parsedName.Count == 1
			&& string.Equals(parsedName[0], IngredientLineResolver.SingularizeToken(keyPhrase[0]), StringComparison.OrdinalIgnoreCase))
		{
			relation = CompoundHeadLost;
		}
		else if (acceptedDesc is null)
		{
			relation = Other;
			missingField = "actualDescriptions";
		}
		else if (HeadsAgree(keyHead, acceptedHead))
		{
			if (keyState != acceptedState)
			{
				relation = StateMismatch;
			}
			else if (keyTier is null || acceptedTier is null)
			{
				relation = Other;
				missingField = keyTier is null ? "expectedDataTypes" : "actualDataTypes";
			}
			else if (!string.Equals(keyTier, acceptedTier, StringComparison.OrdinalIgnoreCase))
			{
				relation = RowChoiceTier;
			}
			else
			{
				relation = SameHeadOtherQualifier;
				keyOnly = QualifierDiff(keyParsed.Qualifiers, acceptedParsed!.Qualifiers, out acceptedOnly);
			}
		}
		else
		{
			relation = SiblingFood;
		}

		return new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			Relation = relation,
			Site = site,
			OverrideKey = overrideKey,
			AcceptedTier = acceptedTier ?? string.Empty,
			KeyTier = keyTier ?? string.Empty,
			AcceptedState = acceptedState.ToString(),
			KeyState = keyState.ToString(),
			ParsedName = atom?.ParsedName ?? string.Empty,
			KeyHead = string.Join(' ', keyPhrase.Select(IngredientLineResolver.SingularizeToken)),
			AcceptedDesc = acceptedDesc ?? string.Empty,
			KeyDesc = keyDesc ?? string.Empty,
			RawText = line.RawText,
			MissingField = missingField,
			KeyOnlyQualifiers = keyOnly,
			AcceptedOnlyQualifiers = acceptedOnly,
		};
	}

	/// <summary>
	/// The key's head phrase: the normalised key tokens up to the first word production calls a
	/// state/modifier word (<see cref="FdcLexicon.ModifierWords"/>, or a word the production
	/// <c>ExtractCandidateState</c>/<c>ExtractCandidateSatisfiers</c> helpers flag). "Bread, crumbs,
	/// dry, grated, plain" yields <c>bread crumbs</c>; "Nuts, almonds, blanched" yields
	/// <c>nut almond</c>. Deterministic in the description alone — the same key in a new recipe,
	/// any amount, any preparation, classifies identically.
	/// </summary>
	/// <param name="keyTokens">The normalised key tokens.</param>
	/// <returns>The head-phrase tokens (possibly empty).</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> keyTokens)
	{
		var phrase = new List<string>();
		foreach (var token in keyTokens)
		{
			if (CarriesStateToken(token))
			{
				return phrase;
			}

			phrase.Add(token);
		}

		return phrase;
	}

	/// <summary>The state ∪ satisfiers mask for a token list, exactly as <see cref="FdcMatcher"/> composes it.</summary>
	/// <param name="tokens">The normalised tokens.</param>
	/// <returns>The combined <see cref="FoodState"/> mask.</returns>
	public static FoodState CombinedState(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	/// <summary>Folds a raw line text the way the production raw-key override lookup does (lower-case, trimmed, content from the first <c>(</c> dropped).</summary>
	/// <param name="rawText">The raw line text.</param>
	/// <returns>The folded lookup key.</returns>
	public static string NormalizeForOverrideKey(string rawText)
	{
		ArgumentNullException.ThrowIfNull(rawText);

#pragma warning disable CA1308 // Reason: parity with FdcMatcher's raw-override lookup (ToLowerInvariant).
		var lowered = rawText.Trim().ToLowerInvariant();
#pragma warning restore CA1308
		var paren = lowered.IndexOf('(', StringComparison.Ordinal);
		return paren >= 0 ? lowered[..paren].Trim() : lowered;
	}

	private static bool HeadsAgree(IReadOnlyList<string> keyHead, IReadOnlyList<string> acceptedHead)
	{
		if (keyHead.Count != acceptedHead.Count)
		{
			return false;
		}

		for (var i = 0; i < keyHead.Count; i++)
		{
			if (!string.Equals(keyHead[i], acceptedHead[i], StringComparison.OrdinalIgnoreCase))
			{
				return false;
			}
		}

		return true;
	}

	private string ClassifySite(TraceAtom? atom)
	{
		if (atom is null)
		{
			return string.Empty;
		}

		return atom.Path switch
		{
			"ranker" when atom.Reused => SiteReuse,
			"ranker" => SiteRanker,
			"override" => SiteOverride,
			"curated" => SiteCurated,
			_ => string.Empty,
		};
	}

	private IReadOnlyList<string> SingularPhrase(string? text) =>
		_normalizer.NormalizeToTokens(text).Select(IngredientLineResolver.SingularizeToken).ToArray();

	private static IReadOnlyList<string> QualifierDiff(IReadOnlyList<string> keyQualifiers, IReadOnlyList<string> acceptedQualifiers, out IReadOnlyList<string> acceptedOnly)
	{
		var keySet = new HashSet<string>(keyQualifiers, StringComparer.OrdinalIgnoreCase);
		var acceptedSet = new HashSet<string>(acceptedQualifiers, StringComparer.OrdinalIgnoreCase);

		keyOnly = keyQualifiers.Where(q => !acceptedSet.Contains(q)).OrderBy(q => q, StringComparer.OrdinalIgnoreCase).ToArray();
		acceptedOnly = acceptedQualifiers.Where(q => !keySet.Contains(q)).OrderBy(q => q, StringComparer.OrdinalIgnoreCase).ToArray();
		return keyOnly;
	}

	private static FdcDataset DatasetOf(string? tier) =>
		tier is not null && Enum.TryParse<FdcDataset>(tier, ignoreCase: true, out var dataset) ? dataset : FdcDataset.None;

	private bool CarriesStateToken(string token)
	{
		if (FdcLexicon.Default.ModifierWords.Contains(token))
		{
			return true;
		}

		_singleTokenScratch[0] = token;
		return FdcMatcher.ExtractCandidateState(_singleTokenScratch) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleTokenScratch) != FoodState.None;
	}
}
