{"content":"using System.Text.Json;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Resolver;
using Microsoft.Extensions.Options;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Reads a HoldoutGate trace JSONL, classifies every <c>auto &amp;&amp; !correct</c> line and writes
/// the TSV (stdout) plus the relation × site summary (stderr). Refuses any trace whose records carry
/// a <c>set</c> other than <c>debug</c> or <c>batch</c> (D-029: no sealed read, ever) and exits 1 on a
/// missing file.
/// </summary>
public sealed class AutoWrongCensusRunner(
	IOptions<AutoWrongCensusOptions> options,
	AutoWrongClassifier classifier,
	OutputWriters writers) : IAutoWrongCensusRunner
{
	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	private readonly AutoWrongCensusOptions _options = options.Value;

	/// <inheritdoc />
	public async Task<int> RunAsync(CancellationToken cancellationToken)
	{
		if (_options.Command == CommandLineArgumentParser.CensusCommand)
		{
			return await RunCensusAsync(cancellationToken).ConfigureAwait(false);
		}

		if (_options.Command == CommandLineArgumentParser.PairsCommand)
		{
			return await RunPairsAsync(cancellationToken).ConfigureAwait(false);
		}

		writers.Error.WriteLine("usage: census <trace.jsonl> | pairs <census.tsv> <trace.jsonl>");
		return 1;
	}

	private async Task<int> RunCensusAsync(CancellationToken cancellationToken)
	{
		var lines = await ReadTraceAsync(_options.TracePath, cancellationToken).ConfigureAwait(false);
		if (lines is null)
		{
			return 1;
		}

		var refused = lines.Where(l => l.Set != "debug" && l.Set != "batch").Select(l => l.Set).Distinct().ToArray();
		if (refused.Length > 0)
		{
			writers.Error.WriteLine($"refused: trace set(s) {string.Join(", ", refused)} are not debug or batch (D-029: no sealed read).");
			return 1;
		}

		var autoWrong = lines.Where(l => l.Auto && !l.Correct).ToArray();
		var results = new List<ClassificationResult>(autoWrong.Length);
		var unknownSite = 0;

		foreach (var line in autoWrong)
		{
			cancellationToken.ThrowIfCancellationRequested();
			var result = classifier.Classify(line);
			if (result.Site.Length == 0)
			{
				unknownSite++;
				writers.Error.WriteLine($"unknown atom path '{line.Atoms.FirstOrDefault(a => a.Outcome == "accepted")?.Path ?? "?"}' on {line.HoldoutId}#{line.LineIndex}; refusing to classify.");
			}

			results.Add(result);
		}

		WriteTsv(results);
		WriteSummary(lines.Length, autoWrong.Length, results);

		return unknownSite > 0 ? 1 : 0;
	}

	private async Task<int> RunPairsAsync(CancellationToken cancellationToken)
	{
		var lines = await ReadTraceAsync(_options.TracePath, cancellationToken).ConfigureAwait(false);
		if (lines is null)
		{
			return 1;
		}

		var refused = lines.Where(l => l.Set != "debug" && l.Set != "batch").Select(l => l.Set).Distinct().ToArray();
		if (refused.Length > 0)
		{
			writers.Error.WriteLine($"refused: trace set(s) {string.Join(", ", refused)} are not debug or batch (D-029: no sealed read).");
			return 1;
		}

		var census = ReadCensus(_options.CensusTsvPath);
		if (census is null)
		{
			return 1;
		}

		var byKey = lines.ToDictionary(l => (l.HoldoutId, l.LineIndex));
		writers.Output.WriteLine("holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText");

		var emitted = 0;
		var unmatched = 0;
		foreach (var row in census)
		{
			cancellationToken.ThrowIfCancellationRequested();
			if (row.Blocker != "window" || (row.Route != "compound" && row.Route != "other"))
			{
				continue;
			}

			if (!byKey.TryGetValue((row.HoldoutId, row.LineIndex), out var line))
			{
				unmatched++;
				continue;
			}

			var atom = line.Atoms.Count > 0 ? line.Atoms[0] : null;
			var keyDesc = line.ExpectedDescriptions.Count > 0 ? line.ExpectedDescriptions[0] : string.Empty;
			var keyHead = string.Join(' ', classifier.KeyHeadPhrase(classifier.Normalizer.NormalizeToTokens(keyDesc)));
			var parsedNameHead = atom is null ? string.Empty : string.Join(' ', SingularizeTokens(classifier.Normalizer.NormalizeToTokens(atom.ParsedName)));

			writers.Output.WriteLine($"{Cell(row.HoldoutId)}\t{row.LineIndex}\t{Cell(parsedNameHead)}\t{Cell(keyHead)}\t{Cell(line.RawText)}");
			emitted++;
		}

		writers.Error.WriteLine($"pairs: emitted={emitted} unmatched={unmatched}");
		return 0;
	}

	private void WriteTsv(IReadOnlyList<ClassificationResult> results)
	{
		writers.Output.WriteLine("holdoutId\tlineIndex\tset\trelation\tsite\toverrideKey\tacceptedTier\tkeyTier\tacceptedState\tkeyState\tparsedName\tkeyHead\tacceptedDesc\tkeyDesc\trawText");
		foreach (var r in results)
		{
			writers.Output.WriteLine($"{Cell(r.HoldoutId)}\t{r.LineIndex}\t{Cell(r.Set)}\t{r.Relation}\t{r.Site}\t{r.OverrideKey}\t{Cell(r.AcceptedTier)}\t{Cell(r.KeyTier)}\t{Cell(r.AcceptedState)}\t{Cell(r.KeyState)}\t{Cell(r.ParsedName)}\t{Cell(r.KeyHead)}\t{Cell(r.AcceptedDesc)}\t{Cell(r.KeyDesc)}\t{Cell(r.RawText)}");
		}
	}

	private void WriteSummary(int traced, int autoWrong, IReadOnlyList<ClassificationResult> results)
	{
		var set = results.Count > 0 ? results[0].Set : "?";
		writers.Error.WriteLine($"autoWrongCensus set={set} traced={traced} autoWrong={autoWrong}");
		writers.Error.WriteLine("relation\tsite\tcount");

		foreach (var relation in results.Select(r => r.Relation).Distinct().OrderBy(v => v, StringComparer.Ordinal))
		{
			foreach (var site in results.Where(r => r.Relation == relation).Select(r => r.Site).Distinct().OrderBy(v => v, StringComparer.Ordinal))
			{
				writers.Error.WriteLine($"{relation}\t{site}\t{results.Count(r => r.Relation == relation && r.Site == site)}");
			}
		}

		var other = results.Count(r => r.Relation == AutoWrongClassifier.RelationOther);
		writers.Error.WriteLine($"other={other}/{autoWrong} ({(autoWrong > 0 ? other * 100.0 / autoWrong : 0.0):F1}%)");

		var missing = results.Where(r => r.MissingField is not null).GroupBy(r => r.MissingField!);
		foreach (var group in missing.OrderBy(g => g.Key, StringComparer.Ordinal))
		{
			writers.Error.WriteLine($"missingField {group.Key}: {group.Count()}");
		}

		var overrides = results.Where(r => r.Site == AutoWrongClassifier.SiteOverride);
		if (overrides.Any())
		{
			writers.Error.WriteLine($"overrideKey yes={overrides.Count(r => r.OverrideKey == "yes")} no={overrides.Count(r => r.OverrideKey == "no")}");
		}

		var tier = results.Where(r => r.Relation == AutoWrongClassifier.RelationRowChoiceTier);
		if (tier.Any())
		{
			writers.Error.WriteLine($"row-choice-tier key higher={tier.Count(r => TierRank(r.KeyTier) > TierRank(r.AcceptedTier))} accepted higher={tier.Count(r => TierRank(r.AcceptedTier) > TierRank(r.KeyTier))}");
		}

		foreach (var r in results.Where(r => r.Relation == AutoWrongClassifier.RelationSameHeadOtherQualifier))
		{
			writers.Error.WriteLine($"qualdiff {r.HoldoutId}#{r.LineIndex} keyOnly=[{string.Join(", ", r.KeyOnlyQualifiers ?? [])}] acceptedOnly=[{string.Join(", ", r.AcceptedOnlyQualifiers ?? [])}]");
		}

		var reuse = results.Where(r => r.Site == AutoWrongClassifier.SiteReuse && r.ParsedName.Length > 0);
		var reuseFalse = reuse.Count(r => !IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(r.ParsedName), ReuseTargetOf(r)));
		if (reuse.Any())
		{
			writers.Error.WriteLine($"reuse lines where ShouldReuse(parsedName, linkedIngredientId) is false: {reuseFalse}/{reuse.Count()}");
		}
	}

	private static string ReuseTargetOf(ClassificationResult r) =>
		r.MissingField is null && r.KeyDesc.Length > 0 ? r.KeyDesc : string.Empty;

	private static int TierRank(string tier) => tier.ToLowerInvariant() switch
	{
		"foundation" => 4,
		"srlegacy" => 3,
		"survey" => 2,
		"branded" => 1,
		_ => 0,
	};

	private static IReadOnlyList<string> SingularizeTokens(IReadOnlyList<string> tokens) =>
		Array.ConvertAll(tokens.ToArray(), t => IngredientLineResolver.SingularizeToken(t));

	private static string Cell(string value) => value.Replace('\t', ' ').Replace('\n', ' ').Replace('\r', ' ');

	private async Task<List<TraceLine>?> ReadTraceAsync(string path, CancellationToken cancellationToken)
	{
		if (!File.Exists(path))
		{
			writers.Error.WriteLine($"missing trace file: {path}");
			return null;
		}

		var lines = new List<TraceLine>();
		var raw = File.ReadLines(path);
		await foreach (var text in raw.LazyAsync().WithCancellation(cancellationToken).ConfigureAwait(false))
		{
			if (string.IsNullOrWhiteSpace(text))
			{
				continue;
			}

			try
			{
				lines.Add(JsonSerializer.Deserialize<TraceLine>(text, JsonOptions)!);
			}
			catch (JsonException ex)
			{
				writers.Error.WriteLine($"unparseable trace line in {path}: {ex.Message}");
				return null;
			}
		}

		return lines;
	}

	private List<(string HoldoutId, int LineIndex, string Blocker, string Route)>? ReadCensus(string path)
	{
		if (!File.Exists(path))
		{
			writers.Error.WriteLine($"missing census TSV: {path}");
			return null;
		}

		var rows = File.ReadLines(path).Where(l => l.Length > 0).ToArray();
		if (rows.Length == 0)
		{
			writers.Error.WriteLine($"empty census TSV: {path}");
			return null;
		}

		var header = rows[0].Split('\t');
		var index = new Dictionary<string, int>(StringComparer.Ordinal);
		for (var i = 0; i < header.Length; i++)
		{
			index.TryAdd(header[i], i);
		}

		foreach (var required in new[] { "holdoutId", "lineIndex", "blocker", "route" })
		{
			if (!index.ContainsKey(required))
			{
				writers.Error.WriteLine($"census TSV {path} lacks column '{required}'");
				return null;
			}
		}

		var result = new List<(string, int, string, string)>(rows.Length - 1);
		foreach (var row in rows[1..])
		{
			var cells = row.Split('\t');
			if (cells.Length <= index["route"] || !int.TryParse(cells[index["lineIndex"]], out var lineIndex))
			{
				continue;
			}

			result.Add((cells[index["holdoutId"]], lineIndex, cells[index["blocker"]], cells[index["route"]]));
		}

		return result;
	}
}
